// Tests of iceberg::rendering::iceberg_core(), the split of a first-order Ambisonics room
// impulse response into the direct sound and early reflections (DSER, one channel from W)
// and the late part (IR_Late, four channels). The split is compared with the reference
// data generated by Iceberg MATLAB v1.0.0 and checked on synthetic edge cases.

#include "io/wav_loader.h"
#include "native/center_time.h"
#include "native/time_shift.h"
#include "rendering/iceberg_core.h"
#include "iceberg_signal.h"
#include "test_helpers.h"

#include <gtest/gtest.h>

#include <Eigen/Dense>

#include <chrono>
#include <cmath>
#include <random>
#include <stdexcept>
#include <string>

namespace {

constexpr double kFs = 44100.0;

using iceberg::test::record_measure;

// === 1. Shape: output preserves input length and channel layout =========

// On the rt_05 IR, DSER must have one channel and IR_Late four, both with the length and
// the sample rate of the IR.
TEST(IcebergCore, ShapePreserved) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto ir = iceberg::io::load_wav(iceberg::test::fixture_file("stages/rt_05/input_ir.wav"));

    const auto out = iceberg::rendering::iceberg_core(ir);

    EXPECT_EQ(out.dser.samples.rows(), ir.samples.rows());
    EXPECT_EQ(out.dser.samples.cols(), 1);
    EXPECT_EQ(out.ir_late.samples.rows(), ir.samples.rows());
    EXPECT_EQ(out.ir_late.samples.cols(), ir.samples.cols());
    EXPECT_DOUBLE_EQ(out.dser.sample_rate,    ir.sample_rate);
    EXPECT_DOUBLE_EQ(out.ir_late.sample_rate, ir.sample_rate);
}

// === 2. cTime split coherence: DSER ends near cTime ======================

// On the rt_05 IR, the last non-zero DSER sample must lie at the onset (ISO 3382, found
// by the automatic time shift) plus the centre time of W, within 5 ms, the slack for the
// edge of the Hann window and the rounding of the window to an even length.
TEST(IcebergCore, DserEndsNearCenterTime) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    // After the auto-shift / window / shift-back chain, the DSER should
    // contain non-zero energy up to sample ~onset + cTime in the original
    // timeline: v1.0.0's centre time is referenced to the ISO 3382 onset
    // (the auto shift), not to the peak or to sample 0.
    const auto ir = iceberg::io::load_wav(iceberg::test::fixture_file("stages/rt_05/input_ir.wav"));

    iceberg::Signal omni;
    omni.samples = ir.samples.col(0);
    omni.sample_rate = ir.sample_rate;
    const double c_time = iceberg::native::center_time(omni);

    const Eigen::Index onset_row = -iceberg::native::time_shift(
        omni, iceberg::native::ShiftMode::Auto).shift_samples;

    const auto out = iceberg::rendering::iceberg_core(ir);

    Eigen::Index last_nonzero = -1;
    for (Eigen::Index i = out.dser.samples.rows() - 1; i >= 0; --i) {
        if (std::abs(out.dser.samples(i, 0)) > 1e-9f) {
            last_nonzero = i;
            break;
        }
    }
    ASSERT_GE(last_nonzero, 0);

    const double last_t  = static_cast<double>(last_nonzero) / kFs;
    const double expect_t = static_cast<double>(onset_row) / kFs + c_time;
    // Allow ±5 ms slack: hann window edge effects + even-bump in
    // time_window can shift the boundary by a few samples.
    record_measure("DSER end vs onset + centre time", std::abs(last_t - expect_t), 0.005, "s");
    EXPECT_NEAR(last_t, expect_t, 0.005)
        << "onset_row=" << onset_row << " c_time=" << c_time
        << " last_nonzero=" << last_nonzero;
}

// === 3. DSER + LR overlap ≈ original IR (channel 0) ======================

// Coarse consistency of the split on the rt_05 IR: DSER plus the W channel of IR_Late
// must reconstruct W with an RMS error below 30 % of the RMS of W. The limit is loose
// because the Hann fade of the direct part and the 50 ms rectangular trim at the end of
// the late part remove energy.
TEST(IcebergCore, DserPlusLrApproximatesIr) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    // Sanity: DSER (mono, the W-derived early part) summed with
    // ir_late.col(0) (W of late part) should reconstruct ir.col(0)
    // approximately. The hann window on the early part and the rectwin
    // 50ms tail trim on the late part introduce systematic deviations
    // — keep tolerance loose.
    const auto ir = iceberg::io::load_wav(iceberg::test::fixture_file("stages/rt_05/input_ir.wav"));
    const auto out = iceberg::rendering::iceberg_core(ir);

    const Eigen::ArrayXf reconstructed =
        out.dser.samples.col(0).array() +
        out.ir_late.samples.col(0).array();
    const Eigen::ArrayXf orig = ir.samples.col(0).array();
    const double rms_orig =
        std::sqrt(orig.square().sum() /
                  static_cast<double>(orig.size()));
    const double rms_diff =
        std::sqrt((reconstructed - orig).square().sum() /
                  static_cast<double>(orig.size()));
    // Loose: ≤ 30 % of original RMS. The hann fade and tail trim
    // remove energy; this just sanity-checks that the split is in the
    // right ballpark, not strict reconstruction.
    record_measure("RMS of (DSER + IR_Late - IR) / RMS of IR", rms_diff / rms_orig, 0.3, "rel");
    EXPECT_LT(rms_diff, 0.3 * rms_orig)
        << "rms_orig=" << rms_orig << " rms_diff=" << rms_diff;
}

// === 4. Throws on empty / degenerate input ===============================

// An IR with no samples (0 x 4) and an IR with no channels (1000 x 0) are rejected with
// std::invalid_argument.
TEST(IcebergCore, ThrowsOnEmptyIr) {
    iceberg::Signal empty;
    empty.samples = Eigen::MatrixXf(0, 4);
    empty.sample_rate = kFs;
    EXPECT_THROW(iceberg::rendering::iceberg_core(empty),
                 std::invalid_argument);

    iceberg::Signal zero_cols;
    zero_cols.samples = Eigen::MatrixXf(1000, 0);
    zero_cols.sample_rate = kFs;
    EXPECT_THROW(iceberg::rendering::iceberg_core(zero_cols),
                 std::invalid_argument);
}

// All-zero IR — step-by-step prediction. Input: 28366 × 4 zeros
// @ fs=44100.
//
// 1. Empty-check passes (rows>0, cols>0).
// 2. omni = ir.col(0) → (28366, 1) zeros.
// 3. time_shift Auto on omni: peak idx 0 → shift_index = 0 (no-op).
// 4. center_time(omni): numBlocks = 8, all-zero energy → p_sq_noise = 0
//    → t1idx0 default = numBlocks-1 → t0idx0 < 0 → fallback. Flat
//    log10(eps) regression → slope = 0 → T_10 = -Inf → NaN-safe
//    sanitize → T_10 = 0. EDC0 = 0. Returns 0 / (0 + eps) = 0.
// 5. time_window(omni_shifted, 0, cTime=0, hann): end_sec=0 hits the
//    "until end" sentinel → window the whole signal. Hann × 0 = 0.
//    DSER intermediate = (28366, 1) zeros.
// 6. time_shift Samples back by 0 → DSER = (28366, 1) zeros.
// 7. time_shift Auto on full IR: same logic → shift_index = 0.
// 8. time_crop(full, cTime=0, 0): start = 1, end = nSamples (sentinel)
//    → cropped = original (28366, 4).
// 9. Resync: zero-prepend by 0 samples → no change.
// 10. time_window([0, track_length - 0.05], rectwin): zeros × rectwin
//     = zeros (input is already zero, regardless of window region).
// 11. time_shift Samples back by 0 → IR_Late = (28366, 4) zeros.
//
// The cTime=0 + "until end" sentinel collision (cTime=0 mathematically
// means "no early part" but the sentinel interprets it as "window the
// whole signal") is irrelevant for zero input — both interpretations
// produce zero output. For non-zero IRs with cTime=0 (degenerate but
// possible), the two interpretations would diverge; that case is not
// exercised here.

// Edge case: an all-zero IR (28366 x 4 at 44.1 kHz), whose centre time is 0, must give an
// all-zero DSER (28366 x 1) and an all-zero IR_Late (28366 x 4), both at the input sample
// rate.
TEST(IcebergCore, AllZeroIr) {
    iceberg::Signal ir;
    ir.samples = Eigen::MatrixXf::Zero(28366, 4);
    ir.sample_rate = kFs;

    const auto out = iceberg::rendering::iceberg_core(ir);

    ASSERT_EQ(out.dser.samples.rows(), 28366);
    ASSERT_EQ(out.dser.samples.cols(), 1);
    EXPECT_EQ(out.dser.samples.cwiseAbs().maxCoeff(), 0.0f);

    ASSERT_EQ(out.ir_late.samples.rows(), 28366);
    ASSERT_EQ(out.ir_late.samples.cols(), 4);
    EXPECT_EQ(out.ir_late.samples.cwiseAbs().maxCoeff(), 0.0f);

    EXPECT_DOUBLE_EQ(out.dser.sample_rate,    kFs);
    EXPECT_DOUBLE_EQ(out.ir_late.sample_rate, kFs);
}

// IR shorter than 50ms tail trim — step-by-step prediction (written
// BEFORE running). Input: 1000 × 4 white-noise (seed 42) @ fs=44100.
// track_length = 1000 / 44100 ≈ 0.0227 s < 0.05 s.
//
// 1. center_time: numBlocks = floor(1000 / 3308) = 0 → fallback path
//    cTime = Σ(E·t) / (Σ(E) + eps), some non-zero value in
//    [0, track_length).
// 2. DSER path: hann-windowed [0, cTime] on shifted signal. Output
//    has length 1000 (full original length, with a hann fade after
//    cTime), non-empty, non-zero energy.
// 3. IR_Late path: time_crop → resync zero-prepend → 1000 × 4.
// 4. time_window([0, track_length - 0.05] = [0, -0.0273], rectwin):
//    end_sec is NEGATIVE → endSampleRaw negative → after bump/clamp
//    windowLength ≤ 0 → empty branch → (0, 4) with sample_rate
//    preserved.
// 5. time_shift Samples on (0, 4) input → (0, 4) (helper handles
//    empty input as a no-op).
//
// Final: DSER non-empty (~1000 samples), IR_Late = (0, 4) empty.
//
// This documents the contract for IRs shorter than the rectwin tail
// trim — not blocking the iceberg pipeline (which always feeds long
// IRs), but a clear failure mode for callers using `iceberg_core`
// outside the pipeline.

// Edge case: an IR of 1000 samples of white noise (23 ms), shorter than the 50 ms trimmed
// from the end of the late part, must give a non-zero DSER of all 1000 samples and an
// empty IR_Late (0 x 4) that keeps the input sample rate, since the window of the late
// part would end before time 0.
TEST(IcebergCore, VeryShortIrBelow50ms) {
    constexpr int kN = 1000;
    iceberg::Signal ir;
    ir.samples = Eigen::MatrixXf(kN, 4);
    std::mt19937 rng(42);
    std::uniform_real_distribution<float> dist(-0.5f, 0.5f);
    for (int i = 0; i < kN; ++i) {
        for (int c = 0; c < 4; ++c) ir.samples(i, c) = dist(rng);
    }
    ir.sample_rate = kFs;

    const auto out = iceberg::rendering::iceberg_core(ir);

    // DSER: full original length (1000), non-zero energy.
    EXPECT_EQ(out.dser.samples.rows(), kN);
    EXPECT_EQ(out.dser.samples.cols(), 1);
    EXPECT_GT(out.dser.samples.cwiseAbs().maxCoeff(), 0.0f);

    // IR_Late: empty (0, 4) — the negative-end_sec window collapsed.
    EXPECT_EQ(out.ir_late.samples.rows(), 0);
    EXPECT_EQ(out.ir_late.samples.cols(), 4);
    EXPECT_DOUBLE_EQ(out.ir_late.sample_rate, kFs);
}

// === v1.0.0: stages/<ir>/core_*.wav, all three shipped IRs =================

// DSER and IR_Late of the rt_05, rt_11 and rt_00 IRs are compared with the reference data
// generated by Iceberg MATLAB v1.0.0; rt_00 uses the anechoic special case (a fixed 10 ms
// rectangular window), as the reference does. Limit: 1e-9 RMS per channel, the rounding
// of the 32-bit float reference files.
TEST(IcebergCore, StagesMatchMatlab) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    for (const auto& [name, anechoic] :
         {std::pair<std::string, bool>{"rt_05", false}, {"rt_11", false}, {"rt_00", true}}) {
        const std::string dir = "stages/" + name + "/";
        const auto ir = iceberg::io::load_wav(iceberg::test::fixture_file(dir + "input_ir.wav"));
        const auto dser_ref =
            iceberg::io::load_wav(iceberg::test::fixture_file(dir + "core_dser.wav"));
        const auto late_ref =
            iceberg::io::load_wav(iceberg::test::fixture_file(dir + "core_ir_late.wav"));

        const auto out = iceberg::rendering::iceberg_core(ir, anechoic);
        ASSERT_EQ(out.dser.samples.rows(), dser_ref.samples.rows()) << name;
        ASSERT_EQ(out.ir_late.samples.rows(), late_ref.samples.rows()) << name;
        ASSERT_EQ(out.ir_late.samples.cols(), late_ref.samples.cols()) << name;

        const auto d = iceberg::test::diff_stats(out.dser.samples, dser_ref.samples);
        const auto l = iceberg::test::diff_stats(out.ir_late.samples, late_ref.samples);
        record_measure(name + " DSER", d.worst_rms, 1e-9, "rms");
        record_measure(name + " IR_Late", l.worst_rms, 1e-9, "rms");
        EXPECT_LT(d.worst_rms, 1e-9) << name;
        EXPECT_LT(l.worst_rms, 1e-9) << name;
    }
}

}  // namespace
